#include <bits/stdc++.h>
using namespace std;

long long arrayMultiply(const vector<int>& arr) {
    long long res = 1;
    for (int x : arr) res *= x;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string n;
    if (!getline(cin, n)) return 0;
    int nLength = (int)n.size();
    if (nLength == 1) {
        cout << n;
        return 0;
    }

    bool allNine = true;
    for (int i = 1; i < nLength; ++i) {
        if (n[i] != '9') {
            allNine = false;
            break;
        }
    }
    if (allNine) {
        vector<int> digits;
        for (char c : n) digits.push_back(c - '0');
        cout << arrayMultiply(digits);
        return 0;
    }

    vector<int> digits;
    for (char c : n) digits.push_back(c - '0');
    long long maxProd = arrayMultiply(digits);

    for (int i = 0; i < nLength - 1; ++i) {
        vector<int> arr = digits;
        arr[i] = arr[i] - 1;
        for (int j = i + 1; j < nLength; ++j) {
            arr[j] = 9;
        }
        for (int j = nLength - 1; j > 0; --j) {
            if (arr[j] == 0 || arr[j] == -1) {
                arr[j] = 9;
                arr[j - 1]--;
            }
        }
        if (arr[0] == 0) {
            arr.erase(arr.begin());
        }
        maxProd = max(maxProd, arrayMultiply(arr));
    }

    cout << maxProd;
    return 0;
}

